def last_stone_weight(stones):
    stones = sorted(stones, reverse=True)
    while len(stones) > 1:
        y, x = stones[0], stones[1]
        stones = stones[2:]
        if y != x:
            stones.append(y - x)
        stones.sort(reverse=True)               # re-sort from scratch every round
    return stones[0] if stones else 0

