import java.util.*;

public class Main {
    static int lastStoneWeight(int[] stones) {
        List<Integer> list = new ArrayList<>();
        for (int s : stones) list.add(s);
        Collections.sort(list, Collections.reverseOrder());
        while (list.size() > 1) {
            int y = list.remove(0), x = list.remove(0);
            if (y != x) list.add(y - x);
            Collections.sort(list, Collections.reverseOrder());   // re-sort from scratch every round
        }
        return list.isEmpty() ? 0 : list.get(0);
    }
}

