import heapq

def last_stone_weight(stones):
    heap = [-s for s in stones]                # negate for a max-heap using heapq's min-heap
    heapq.heapify(heap)
    while len(heap) > 1:
        y = -heapq.heappop(heap)
        x = -heapq.heappop(heap)
        if y != x:
            heapq.heappush(heap, -(y - x))       # O(log n), no full re-sort
    return -heap[0] if heap else 0

